pub fn create_checkpoint_dir(config: CheckpointConfig) -> Result(Nil, String) {
  let dir_result = case file_exists(config.checkpoint_dir) {
    True -> Ok(Nil)
    False -> create_directory_recursive(config.checkpoint_dir)
  }
  use _ <- result.try(dir_result)
  case file_exists(config.backup_dir) {
    True -> Ok(Nil)
    False -> create_directory_recursive(config.backup_dir)
  }
}

pub fn save_checkpoint(
  model_state: Dict(String, Dynamic),
  optimizer_state: Option(Dict(String, Dynamic)),
  scheduler_state: Option(Dict(String, Dynamic)),
  config: CheckpointConfig,
  step: Int,
  loss: Float,
  additional_metadata: Dict(String, Dynamic),
) -> Result(String, String) {
  case step % config.save_every_n_steps {
    0 -> Nil
    _ ->
      return Error(
        "Step " <> int.to_string(step) <> " not divisible by save interval "
          <> int.to_string(config.save_every_n_steps),
      )
  }
  use _ <- result.try(create_checkpoint_dir(config))
  let timestamp = get_current_timestamp_millis()
  let git_hash = get_git_hash()
  let hyperparameters =
    dict.merge(
      dict.map_values(config.metadata, fn(_, v) { dynamic.from(v) }),
      additional_metadata,
    )
  let hardware_info = get_system_info()
  let metadata =
    CheckpointMetadata(
      model_version: config.version,
      step: step,
      loss: loss,
      timestamp: timestamp,
      hardware: hardware_info,
      git_hash: git_hash,
      hyperparameters: hyperparameters,
      optimizer_state: optimizer_state,
      checksum: "",
      size_bytes: 0,
      compression_ratio: 0.0,
      encryption_used: option.is_some(config.encryption_key),
      replicated_to: [],
      audit_entries: [],
      cost_estimate: 0.0,
      tier: "hot",
    )
  let full_state =
    dict.insert(model_state, "metadata", dynamic.from(metadata_to_json(metadata)))
  let checkpoint_name =
    "checkpoint_step_"
    <> int.to_string(step)
    <> "_"
    <> int.to_string(timestamp)
  let checkpoint_path_base = config.checkpoint_dir <> "/" <> checkpoint_name
  let checkpoint_path = case config.format {
    SafeTensors -> checkpoint_path_base <> ".safetensors"
    Pickle -> checkpoint_path_base <> ".pkl"
    Json -> checkpoint_path_base <> ".json"
    Protobuf -> checkpoint_path_base <> ".pb"
    MsgPack -> checkpoint_path_base <> ".msgpack"
    Capnp -> checkpoint_path_base <> ".capnp"
    Custom(fmt) -> checkpoint_path_base <> "." <> fmt
  }
  use _ <- result.try(save_state_to_file(full_state, checkpoint_path, config))
  let checksum = compute_checksum(checkpoint_path)
  let size = get_file_size(checkpoint_path)
  let compressed_size_float = case config.compression {
    True -> int.to_float(size) *. 0.7
    False -> int.to_float(size)
  }
  let compression_ratio = case size > 0 {
    True -> compressed_size_float /. int.to_float(size)
    False -> 1.0
  }
  let updated_metadata =
    CheckpointMetadata(
      ..metadata,
      checksum: checksum,
      size_bytes: size,
      compression_ratio: compression_ratio,
    )
  let updated_state =
    dict.insert(
      full_state,
      "metadata",
      dynamic.from(metadata_to_json(updated_metadata)),
    )
  use _ <- result.try(save_state_to_file(updated_state, checkpoint_path, config))
  case config.versioning_enabled {
    True -> version_checkpoint(checkpoint_path, step)
    False -> Nil
  }
  case config.incremental_enabled {
    True -> create_incremental_backup(checkpoint_path, config.backup_dir)
    False -> Nil
  }
  case list.is_empty(config.replication_targets) {
    False -> replicate_checkpoint(checkpoint_path, config.replication_targets)
    True -> Nil
  }
  case config.audit_log_enabled {
    True -> log_audit_entry(checkpoint_path, updated_metadata)
    False -> Nil
  }
  case config.cost_tracking_enabled {
    True -> {
      let _ = estimate_cost(checkpoint_path, updated_metadata)
      Nil
    }
    False -> Nil
  }
  case config.tiering_enabled {
    True -> tier_checkpoint(checkpoint_path, updated_metadata.tier)
    False -> Nil
  }
  case config.validation_enabled {
    True -> {
      let _ = validate_checkpoint(checkpoint_path, updated_metadata)
      Nil
    }
    False -> Nil
  }
  case config.notification_url {
    option.Some(_) ->
      notify_checkpoint_saved(checkpoint_path, config.notification_url)
    option.None -> Nil
  }
  manage_checkpoints(config, checkpoint_path)
  Ok(checkpoint_path)
}

pub fn load_checkpoint(
  path: String,
  config: CheckpointConfig,
) -> Result(CheckpointState, String) {
  let full_path = case config.format {
    SafeTensors -> path <> ".safetensors"
    Pickle -> path <> ".pkl"
    Json -> path <> ".json"
    Protobuf -> path <> ".pb"
    MsgPack -> path <> ".msgpack"
    Capnp -> path <> ".capnp"
    Custom(fmt) -> path <> "." <> fmt
  }
  use data <- result.try(read_file(full_path))
  let decrypted = case config.encryption_key {
    option.Some(key) -> decrypt_aes(data, key)
    option.None -> data
  }
  let decompressed = case config.compression {
    True -> decompress_gzip(decrypted)
    False -> decrypted
  }
  use loaded_state <- result.try(deserialize_state(decompressed, config.format))
  use metadata_value <- result.try(
    dict.get(loaded_state, "metadata")
    |> result.replace_error("Missing metadata"),
  )
  use meta <- result.try(
    decode_metadata_from_dynamic(metadata_value)
    |> result.map_error(fn(_) { "Failed to decode metadata" }),
  )
  let model_state = dict.delete(loaded_state, "metadata")
  let optimizer_state = case config.save_optimizer {
    True -> meta.optimizer_state
    False -> option.None
  }
  case dict.is_empty(config.access_control) {
    False -> {
      use _ <- result.try(check_access_control(path, config.access_control))
      Ok(CheckpointState(
        model_state: model_state,
        optimizer_state: optimizer_state,
        scheduler_state: option.None,
        metadata: meta,
      ))
    }
    True ->
      Ok(CheckpointState(
        model_state: model_state,
        optimizer_state: optimizer_state,
        scheduler_state: option.None,
        metadata: meta,
      ))
  }
}

pub fn save_state_to_file(
  state: Dict(String, Dynamic),
  path: String,
  config: CheckpointConfig,
) -> Result(Nil, String) {
  let serialized = serialize_state(state, config.format)
  let compressed = case config.compression {
    True -> compress_gzip(serialized)
    False -> serialized
  }
  let encrypted = case config.encryption_key {
    option.Some(key) -> encrypt_aes(compressed, key)
    option.None -> compressed
  }
  write_file(path, encrypted)
}

pub fn serialize_state(
  state: Dict(String, Dynamic),
  format: CheckpointFormat,
) -> String {
  case format {
    SafeTensors -> serialize_safetensors(state)
    Pickle -> serialize_pickle(state)
    Json -> serialize_json(state)
    Protobuf -> serialize_protobuf(state)
    MsgPack -> serialize_msgpack(state)
    Capnp -> serialize_capnp(state)
    Custom(_) -> serialize_json(state)
  }
}

pub fn deserialize_state(
