pub fn compute_checksum(path: String) -> String {
  case read_file(path) {
    Ok(data) -> {
      let hash = crypto.hash(crypto.Sha256, <<data:utf8>>)
      bit_array.base16_encode(hash)
    }
    Error(_) -> ""
  }
}

