pub fn create_incremental_backup(path: String, backup_dir: String) -> Nil {
  let filename = case string.split(path, "/") {
    [] -> "unknown"
    parts -> case list.last(parts) {
      Ok(name) -> name
      Error(_) -> "unknown"
    }
  }
  let backup_path = backup_dir <> "/" <> filename
  let _ = copy_file(path, backup_path)
  Nil
}

