pub fn manage_checkpoints(config: CheckpointConfig, _latest: String) -> Nil {
  case list_directory(config.checkpoint_dir) {
    Ok(files) -> {
      let checkpoints =
        list.filter(files, fn(f) { string.contains(f, "checkpoint_step_") })
      case list.length(checkpoints) > config.max_checkpoints {
        True -> {
          let sorted =
            list.sort(checkpoints, fn(a, b) {
              let step_a = extract_step_from_filename(a)
              let step_b = extract_step_from_filename(b)
              int.compare(step_a, step_b)
            })
          let to_delete = list.take(sorted, list.length(sorted) - config.max_checkpoints)
          list.each(to_delete, fn(f) {
            let full_path = config.checkpoint_dir <> "/" <> f
            let _ = delete_file(full_path)
            Nil
          })
        }
        False -> Nil
      }
    }
    Error(_) -> Nil
  }
}

