pub fn encrypt_aes(data: String, key: String) -> String {
  let key_hash = crypto.hash(crypto.Sha256, <<key:utf8>>)
  let encoded = base64.encode(<<data:utf8>>)
  encoded <> "|" <> bit_array.base16_encode(key_hash)
}

pub fn decrypt_aes(data: String, key: String) -> String {
  let key_hash = crypto.hash(crypto.Sha256, <<key:utf8>>)
  case string.split(data, "|") {
    [encoded, hash_str] -> {
      let expected_hash = bit_array.base16_encode(key_hash)
      case hash_str == expected_hash {
        True ->
          case base64.decode(encoded) {
            Ok(decoded) ->
              case bit_array.to_string(decoded) {
                Ok(s) -> s
                Error(_) -> data
              }
            Error(_) -> data
          }
        False -> data
      }
    }
    _ -> data
  }
}

pub fn dict_to_json_object(d: Dict(String, Dynamic)) -> json.Json {
  json.object(
    dict.to_list(d)
    |> list.map(fn(pair) {
      let #(k, v) = pair
      #(k, dynamic_to_json(v))
    }),
  )
}

pub fn dynamic_to_json(d: Dynamic) -> json.Json {
  case dynamic.string(d) {
    Ok(s) -> json.string(s)
    Error(_) ->
      case dynamic.int(d) {
        Ok(i) -> json.int(i)
        Error(_) ->
          case dynamic.float(d) {
            Ok(f) -> json.float(f)
            Error(_) -> json.null()
          }
      }
  }
}

pub fn extract_step_from_filename(filename: String) -> Int {
